from functools import wraps

# Task 1: Define simple_logger decorator
def simple_logger(func):
    def wrapper():
        print('▶️ Running function...')
        func()
        print('✅ Done!')
    return wrapper

# Task 2: Apply simple_logger to say_python
@simple_logger
def say_python():
    print('Python is awesome!')

# Task 3: Define smart_logger decorator
def smart_logger(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f'▶️ Starting {func.__name__}')
        result = func(*args, **kwargs)
        print(f'✅ Finished {func.__name__}')
        return result
    return wrapper

# Task 4: Apply smart_logger to multiply
@smart_logger
def multiply(x, y):
    return x * y

# Task 5: Define repeat decorator with parameter
def repeat(times):
    def decorator_repeat(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator_repeat

# Task 6: Apply repeat to cheer
@repeat(times=4)
def cheer(name):
    print(f'Go {name}!')

# Test your functions
print('--- Testing say_python ---')
say_python()

print('\n--- Testing multiply ---')
result = multiply(4, 3)
print(f'Product: {result}')

print('\n--- Testing cheer ---')
cheer('Python')
